<?php /** @var array $projects @var string $assetBase */ ?><section class="l-page-hero"><p class="l-eyebrow">Our work</p><h1>Property transformations.</h1><p>Before-and-after project stories show the work more clearly than promises can.</p></section><section class="l-section l-project-list"><?php foreach ($projects as $project): $before=$project['before_image_url']?:$assetBase.'/assets/images/services/property-cleanup.webp'; $after=$project['after_image_url']?:$assetBase.'/assets/images/services/landscape-installation.webp'; ?><article class="l-project"><div class="l-before-after"><figure><img src="<?= e_attr($before) ?>" alt="Before <?= e_attr($project['name']) ?>"><figcaption>Before</figcaption></figure><figure><img src="<?= e_attr($after) ?>" alt="After <?= e_attr($project['name']) ?>"><figcaption>After</figcaption></figure></div><div><p class="l-eyebrow"><?= e($project['location_label']) ?></p><h2><?= e($project['name']) ?></h2><p><?= e($project['summary']) ?></p><p><strong>Services:</strong> <?= e($project['services_used']) ?></p><?php if ($project['completed_on']): ?><p><strong>Completed:</strong> <?= e($project['completed_on']) ?></p><?php endif; ?></div></article><?php endforeach; ?></section>
